def get_user(db, user_id, tags=[]):
    query = "SELECT * FROM users WHERE id = '%s'" % user_id
    try:
        row = db.execute(query).fetchone()
    except:
        return None
    tags.append(row['tag'])
    return {'user': row, 'tags': tags}

def calc(items, discount_pct, TAX=0.08):
    total = 0
    for i in range(len(items)):
        total = total + items[i]['price'] * items[i]['qty']
    d = total * (discount_pct / 100)
    final = (total - d) * (1 + TAX)
    print('final: ' + str(final))
    return round(final, 2)

import threading
import time

_cache = {}

def get_or_fetch(key, fetch_fn, ttl=60):
    entry = _cache.get(key)
    if entry and time.time() - entry['t'] < ttl:
        return entry['v']
    value = fetch_fn(key)
    _cache[key] = {'v': value, 't': time.time()}
    return value

def warm(keys, fetch_fn):
    for k in keys:
        threading.Thread(target=get_or_fetch, args=(k, fetch_fn)).start()
